import { createTool } from '@mastra/core/tools';
import { z } from 'zod';

const searchResultSchema = z.object({
  title: z.string(),
  url: z.string(),
  description: z.string(),
  age: z.string().optional(),
});

export const braveSearchTool = createTool({
  id: 'brave-web-search',
  description: 'Search the web using Brave Search API for information, best practices, and examples',
  inputSchema: z.object({
    query: z.string().describe('The search query to find relevant information'),
    count: z.number().optional().default(5).describe('Number of results to return (1-20)'),
  }),
  outputSchema: z.object({
    results: z.array(searchResultSchema),
    query: z.string(),
    total_results: z.number().optional(),
  }),
  execute: async ({ context }) => {
    const { query, count = 5 } = context;

    // Ensure we have API key
    const apiKey = process.env.BRAVE_SEARCH_API_KEY;
    if (!apiKey) {
      throw new Error('BRAVE_SEARCH_API_KEY environment variable is not set');
    }

    try {
      // Call Brave Search API
      const response = await fetch(
        `https://api.search.brave.com/res/v1/web/search?q=${encodeURIComponent(query)}&count=${count}`,
        {
          headers: {
            'Accept': 'application/json',
            'X-Subscription-Token': apiKey,
          },
        }
      );

      if (!response.ok) {
        throw new Error(`Brave Search API error: ${response.status} ${response.statusText}`);
      }

      const data = await response.json();

      // Transform results to our schema
      const results = data.web?.results?.map((result: any) => ({
        title: result.title || '',
        url: result.url || '',
        description: result.description || result.snippet || '',
        age: result.age || undefined,
      })) || [];

      return {
        results,
        query,
        total_results: data.web?.total || 0,
      };
    } catch (error) {
      console.error('Brave Search error:', error);
      throw new Error(`Failed to search web: ${error instanceof Error ? error.message : String(error)}`);
    }
  },
});

